"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raising the CPU limit from 0.5 to 0.75 cores should reduce throttling and allow the container to meet its CPU demand without hitting the limit.",
  "rationale": "The container is consistently near its CPU limit (0.498/0.5) and throttled 58% of the time, causing readiness probe timeouts. Increasing the limit to 0.75 cores (1.5x current) should alleviate throttling without requiring node-level changes. The rollout_recent flag suggests the new version may have higher CPU usage, but the limit is the immediate constraint here.",
